From 7d86aa41c073c4e7eb75fd2e674f1fd8f289728a Mon Sep 17 00:00:00 2001
From: Chengfeng Ye <dg573847474@gmail.com>
Date: Fri, 6 Mar 2026 03:14:02 +0000
Subject: [PATCH] mctp: route: hold key->lock in mctp_flow_prepare_output()

mctp_flow_prepare_output() checks key->dev and may call
mctp_dev_set_key(), but it does not hold key->lock while doing so.

mctp_dev_set_key() and mctp_dev_release_key() are annotated with
__must_hold(&key->lock), so key->dev access is intended to be
serialized by key->lock. The mctp_sendmsg() transmit path reaches
mctp_flow_prepare_output() via mctp_local_output() -> mctp_dst_output()
without holding key->lock, so the check-and-set sequence is racy.

Example interleaving:

  CPU0                                  CPU1

diff --git a/net/mctp/route.c b/net/mctp/route.c
index 0381377ab760..59ad60b88563 100644
--- a/net/mctp/route.c
+++ b/net/mctp/route.c
@@ -359,6 +359,7 @@ static void mctp_flow_prepare_output(struct sk_buff *skb, struct mctp_dev *dev)
 {
 	struct mctp_sk_key *key;
 	struct mctp_flow *flow;
+	unsigned long flags;

 	flow = skb_ext_find(skb, SKB_EXT_MCTP);
 	if (!flow)
@@ -366,12 +367,14 @@ static void mctp_flow_prepare_output(struct sk_buff *skb, struct mctp_dev *dev)

 	key = flow->key;

-	if (key->dev) {
+	spin_lock_irqsave(&key->lock, flags);
+
+	if (!key->dev)
+		mctp_dev_set_key(dev, key);
+	else
 		WARN_ON(key->dev != dev);
-		return;
-	}

-	mctp_dev_set_key(dev, key);
+	spin_unlock_irqrestore(&key->lock, flags);
 }
 #else
 static void mctp_skb_set_flow(struct sk_buff *skb, struct mctp_sk_key *key) {}
-- 
2.34.1

The code statements that lead to the bug are:
if (key->dev) {
    WARN_ON(key->dev != dev);
    return;
}
mctp_dev_set_key(dev, key);
Reason:
These statements check and modify key->dev without holding key->lock, creating a race condition. Concurrent calls from different CPUs can both see key->dev as NULL, then both call mctp_dev_set_key, causing one reference to be overwritten and leaked.

The code statements that fix the bug are:
spin_lock_irqsave(&key->lock, flags);
if (!key->dev)
    mctp_dev_set_key(dev, key);
else
    WARN_ON(key->dev != dev);
spin_unlock_irqrestore(&key->lock, flags);
Reason:
Acquiring key->lock before the check-and-set operation serializes access to key->dev, preventing concurrent modifications. This ensures only one mctp_dev_set_key call occurs and the reference is correctly tracked.

